## Plan

### 1. `src/api/account.ts` — add imports and the route

Imports become:

```ts
import { createUser, getUser, publicUser, UserError } from "../auth/users.ts";
import { createSession, revokeSession } from "../auth/session.ts";
```

New route appended to `accountRoutes` (after `/api/logout`):

```ts
{
  method: "POST",
  path: "/api/signup",
  handler: (req) => {
    try {
      const email = field(req.body, "email");
      const name = field(req.body, "name");
      const password = field(req.body, "password");
      if (!email || !name || !password) return json(400, { error: "email, name and password are required" });
      const user = createUser(email, name, password);
      const session = createSession(user.id);
      return json(201, { token: session.token, user: publicUser(user) });
    } catch (err) {
      if (err instanceof UserError) return json(400, { error: err.message });
      throw err;
    }
  },
},
```

(Same session-start pattern as `login` in routes.ts:8-13 — `createSession(user.id)` → `session.token`; router's catch-all stays a safety net for non-`UserError` errors.)

### 2. `test/signup.test.ts`

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { createUser, resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates the user, signs them in, returns 201 with token and publicUser", async () => {
  const res = await call("POST", "/api/signup", { email: "Ada@Example.com", name: "Ada", password: "correct horse" });
  assert.equal(res.status, 201);
  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.deepEqual(user, { id: user.id, email: "ada@example.com", name: "Ada" });
  assert.equal((await call("GET", "/api/me", undefined, token)).status, 200);
});

test("signup rejects a duplicate email and weak password with 400", async () => {
  createUser("ada@example.com", "Ada", "correct horse");
  const dup = await call("POST", "/api/signup", { email: "ada@example.com", name: "Ada2", password: "correct horse" });
  assert.equal(dup.status, 400);
  assert.match(String((dup.body as { error: string }).error), /already registered/);
  const weak = await call("POST", "/api/signup", { email: "bob@example.com", name: "Bob", password: "short" });
  assert.equal(weak.status, 400);
});

test("signup rejects missing fields with 400", async () => {
  assert.equal((await call("POST", "/api/signup", { email: "a@b.co" })).status, 400);
});
```

No changes to `routes.ts` (it already spreads `accountRoutes` at routes.ts:29). Verify with `npm test` and `npm run typecheck`.
